#!/usr/bin/env python3
"""CSV Insights — a dependency-free command-line CSV analytics tool.

See SPEC.md and README.md for usage.
"""
import argparse
import csv
import json
import sys
from decimal import Decimal, InvalidOperation


def fail(message):
    """Print a useful message to stderr and exit non-zero."""
    sys.stderr.write("error: " + message + "\n")
    sys.exit(1)


def format_decimal(value):
    """Render a Decimal as a plain, minimal decimal string.

    Scientific notation is avoided (plain fixed form); trailing fractional
    zeros are removed so that ``3.00`` becomes ``3`` and ``2.50`` becomes
    ``2.5``. ``0`` is rendered as ``"0"`` (never ``"-0"``).
    """
    if value == 0:
        return "0"
    text = format(value, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text


def parse_filter(spec):
    """Parse a ``COLUMN=VALUE`` filter specification."""
    if "=" not in spec:
        raise ValueError("malformed filter %r: expected COLUMN=VALUE" % spec)
    column, value = spec.split("=", 1)
    if column == "":
        raise ValueError("malformed filter %r: empty column name" % spec)
    return column, value


def load_csv(path):
    """Read and validate the input CSV, returning (header, rows)."""
    try:
        with open(path, newline="", encoding="utf-8") as handle:
            rows = list(csv.reader(handle))
    except FileNotFoundError:
        raise ValueError("input file not found: %s" % path)
    except csv.Error as exc:
        raise ValueError("malformed CSV in %s: %s" % (path, exc))
    except OSError as exc:
        raise ValueError("could not read %s: %s" % (path, exc))

    if not rows:
        raise ValueError("input file is empty: %s" % path)
    header = rows[0]
    if not header:
        raise ValueError("header is empty: %s" % path)
    if any(name == "" for name in header):
        raise ValueError("header contains empty name(s): %s" % path)
    if len(set(header)) != len(header):
        raise ValueError("duplicate header name(s): %s" % path)

    width = len(header)
    data = rows[1:]
    for offset, row in enumerate(data, start=1):
        if len(row) != width:
            raise ValueError(
                "row %d has %d field(s); expected %d" % (offset, len(row), width)
            )
    return header, data


def apply_filters(header, data, filters):
    """Return [(index, row)] for rows matching every filter (AND)."""
    checks = []
    for column, value in filters:
        if column not in header:
            raise ValueError("unknown column in --where: %r" % column)
        checks.append((header.index(column), value))
    matched = []
    for index, row in enumerate(data, start=1):
        if all(row[i] == v for i, v in checks):
            matched.append((index, row))
    return matched


def to_decimal(text, index, column):
    """Convert a cell to Decimal, reporting the row and column on failure."""
    if text.strip() == "":
        raise ValueError(
            "row %d, column %r: blank value is not numeric" % (index, column)
        )
    try:
        value = Decimal(text)
    except InvalidOperation:
        raise ValueError(
            "row %d, column %r: invalid numeric value %r" % (index, column, text)
        )
    if not value.is_finite():
        raise ValueError(
            "row %d, column %r: invalid numeric value %r" % (index, column, text)
        )
    return value


def aggregate(header, rows, group_col, sum_col, avg_col):
    """Group rows and compute optional sum/avg per group, sorted by group."""
    gidx = header.index(group_col)
    sidx = header.index(sum_col) if sum_col is not None else None
    aidx = header.index(avg_col) if avg_col is not None else None

    sums = {}
    avg_totals = {}
    counts = {}
    for index, row in rows:
        group = row[gidx]
        if group not in counts:
            counts[group] = 0
            sums[group] = Decimal(0)
            avg_totals[group] = Decimal(0)
        counts[group] += 1
        if sidx is not None:
            sums[group] += to_decimal(row[sidx], index, sum_col)
        if aidx is not None:
            avg_totals[group] += to_decimal(row[aidx], index, avg_col)

    results = []
    for group in sorted(counts):
        entry = {group_col: group}
        if sidx is not None:
            entry["sum_" + sum_col] = format_decimal(sums[group])
        if aidx is not None:
            entry["avg_" + avg_col] = format_decimal(
                avg_totals[group] / Decimal(counts[group])
            )
        results.append(entry)
    return results


def emit_json(results, columns):
    payload = [{col: row[col] for col in columns} for row in results]
    sys.stdout.write(json.dumps(payload) + "\n")


def emit_csv(results, columns):
    writer = csv.writer(sys.stdout, lineterminator="\n")
    writer.writerow(columns)
    for row in results:
        writer.writerow([row[col] for col in columns])


def build_parser():
    parser = argparse.ArgumentParser(
        prog="csv-insights",
        description="Dependency-free CSV analytics tool.",
    )
    parser.add_argument("input", help="path to input CSV file")
    parser.add_argument(
        "--where",
        action="append",
        metavar="COLUMN=VALUE",
        help="keep rows where COLUMN equals VALUE (repeatable; AND-combined)",
    )
    parser.add_argument("--group-by", metavar="COLUMN", dest="group_by")
    parser.add_argument("--sum", metavar="COLUMN", dest="sum_col")
    parser.add_argument("--avg", metavar="COLUMN", dest="avg_col")
    parser.add_argument(
        "--output",
        choices=["json", "csv"],
        default="json",
        help="output format (default: json)",
    )
    return parser


def run(argv):
    parser = build_parser()
    args = parser.parse_args(argv)

    try:
        header, data = load_csv(args.input)
    except ValueError as exc:
        fail(str(exc))

    try:
        filters = [parse_filter(spec) for spec in (args.where or [])]
    except ValueError as exc:
        fail(str(exc))

    try:
        rows = apply_filters(header, data, filters)
    except ValueError as exc:
        fail(str(exc))

    for label, column in (
        ("--group-by", args.group_by),
        ("--sum", args.sum_col),
        ("--avg", args.avg_col),
    ):
        if column is not None and column not in header:
            fail("unknown column in %s: %r" % (label, column))

    if (args.sum_col is not None or args.avg_col is not None) and args.group_by is None:
        fail("--sum and --avg require --group-by")

    if args.group_by is not None or args.sum_col is not None or args.avg_col is not None:
        columns = []
        if args.group_by is not None:
            columns.append(args.group_by)
        if args.sum_col is not None:
            columns.append("sum_" + args.sum_col)
        if args.avg_col is not None:
            columns.append("avg_" + args.avg_col)
        try:
            results = aggregate(header, rows, args.group_by, args.sum_col, args.avg_col)
        except ValueError as exc:
            fail(str(exc))
    else:
        columns = header
        results = [dict(zip(header, row)) for _, row in rows]

    if args.output == "json":
        emit_json(results, columns)
    else:
        emit_csv(results, columns)
    return 0


def main():
    return run(sys.argv[1:])


if __name__ == "__main__":
    sys.exit(main())
